mapper.select:
SELECT material.source_package_phone_id AS phone_id, material.source_allocation_version AS allocation_version, execution_row.task_id, execution_row.seq AS execution_seq, material.pull_status, material.pull_reason_code, material.active_pull_attempt_id AS active_attempt_id, material.pull_call_id, material.pull_failure_count, parent_task.status AS task_status, parent_task.deleted_at AS task_deleted_at, execution_row.execution_status, (EXISTS ( SELECT 1 FROM pull_task_pull_call_member_attempt current_attempt WHERE current_attempt.group_execution_id = material.group_execution_id AND current_attempt.participant_type = #{materialType} AND current_attempt.participant_ref_id = material.id AND current_attempt.protocol_outcome = #{unknownOutcome} AND (current_attempt.execution_state IS NULL OR current_attempt.execution_state <> #{notStartedState}) ) OR EXISTS ( SELECT 1 FROM pull_task_material_member prior_material JOIN pull_task_group_execution prior_execution ON prior_execution.id = prior_material.group_execution_id WHERE prior_execution.task_id = execution_row.task_id AND prior_execution.seq = execution_row.seq AND prior_execution.attempt_no < execution_row.attempt_no AND prior_material.source_package_phone_id = material.source_package_phone_id AND prior_material.source_allocation_version = material.source_allocation_version AND (prior_material.pull_status IN #{status} OR EXISTS ( SELECT 1 FROM pull_task_pull_call_member_attempt prior_attempt WHERE prior_attempt.group_execution_id = prior_material.group_execution_id AND prior_attempt.participant_type = #{materialType} AND prior_attempt.participant_ref_id = prior_material.id AND prior_attempt.protocol_outcome = #{unknownOutcome} AND (prior_attempt.execution_state IS NULL OR prior_attempt.execution_state <> #{notStartedState}) )) )) AS uncertain_history, EXISTS ( SELECT 1 FROM pull_task_material_member prior_material JOIN pull_task_group_execution prior_execution ON prior_execution.id = prior_material.group_execution_id WHERE prior_execution.task_id = execution_row.task_id AND prior_execution.seq = execution_row.seq AND prior_execution.attempt_no < execution_row.attempt_no AND prior_material.source_package_phone_id = material.source_package_phone_id AND prior_material.source_allocation_version = material.source_allocation_version AND (prior_material.pull_status IN #{status} OR prior_material.pull_failure_count > 0) ) AS prior_consumed FROM pull_task_material_member material JOIN pull_task_group_execution execution_row ON execution_row.id = material.group_execution_id JOIN pull_task parent_task ON parent_task.id = execution_row.task_id WHERE material.source_package_phone_id IS NOT NULL AND material.source_allocation_version IS NOT NULL AND execution_row.id IN #{id}
AND material.id IN #{id}
AND NOT EXISTS ( SELECT 1 FROM pull_task_group_execution newer WHERE newer.task_id = execution_row.task_id AND newer.seq = execution_row.seq AND newer.attempt_no > execution_row.attempt_no ) ORDER BY execution_row.id, material.member_seq

SELECT DISTINCT normalized_phone FROM pull_task_material_member
WHERE pull_status = #{failedStatus} AND pull_result_at >= #{cutoff}
  AND pull_reason_code IN
  #{reason}
  AND normalized_phone IN
  #{phone}

SELECT EXISTS (
  SELECT 1 FROM pull_task_group_execution execution_row
  JOIN pull_task parent_task ON parent_task.id = execution_row.task_id
  WHERE execution_row.source_package_id = #{packageId}
    AND parent_task.deleted_at IS NULL
    AND parent_task.status NOT IN
    #{status}
)
